CREATE TABLE "chapters" (
    "id" bigint NOT NULL,
    "act" bigint,
    "scene" bigint,
    "description" text,
    "work_id" bigint,
    PRIMARY KEY ("id")
);

CREATE TABLE "characters" (
    "id" bigint NOT NULL,
    "charname" text,
    "abbrev" text,
    "description" text,
    PRIMARY KEY ("id")
);

CREATE TABLE "paragraphs" (
    "id" bigint NOT NULL,
    "paragraphnum" bigint,
    "plaintext" text,
    "character_id" bigint,
    "chapter_id" bigint,
    PRIMARY KEY ("id")
);

CREATE TABLE "works" (
    "id" bigint NOT NULL,
    "title" text,
    "longtitle" text,
    "date" bigint,
    "genretype" text,
    PRIMARY KEY ("id")
);

